/**
 * Build a `srcset` string from an image path by inserting `@<width>w`
 * variant suffixes. Only includes widths that would have been generated
 * (i.e. the original image is wider than the variant width).
 *
 * Variants are generated by `scripts/generate-responsive-images.mjs` at
 * 400w, 800w, 1200w, and 1920w for images wider than 1200px.
 */

export const RESPONSIVE_WIDTHS = [400, 800, 1200, 1920] as const;
export const MIN_ORIGINAL_WIDTH = 1200;

function variantPath(src: string, width: number): string {
  const dotIndex = src.lastIndexOf(".");
  if (dotIndex === -1) return `${src}@${width}w`;
  return `${src.slice(0, dotIndex)}@${width}w${src.slice(dotIndex)}`;
}

export function buildSrcset(
  src: string,
  originalWidth?: number,
): string | undefined {
  if (!originalWidth || originalWidth <= MIN_ORIGINAL_WIDTH) {
    return undefined;
  }

  const candidates = RESPONSIVE_WIDTHS.flatMap((w) =>
    w < originalWidth ? [`${variantPath(src, w)} ${w}w`] : [],
  );

  candidates.push(`${src} ${originalWidth}w`);

  return candidates.join(", ");
}

export type ResponsiveImage = {
  src: string;
  width: number;
  height: number;
};

export function buildSrcSetArray(
  src: string,
  originalWidth?: number,
  originalHeight?: number,
): ResponsiveImage[] | undefined {
  if (!originalWidth || !originalHeight || originalWidth <= MIN_ORIGINAL_WIDTH) {
    return undefined;
  }

  const aspectRatio = originalHeight / originalWidth;
  const variants: ResponsiveImage[] = RESPONSIVE_WIDTHS.flatMap((w) =>
    w < originalWidth
      ? [{
          src: variantPath(src, w),
          width: w,
          height: Math.round(w * aspectRatio),
        }]
      : [],
  );

  variants.push({ src, width: originalWidth, height: originalHeight });

  return variants;
}
